BEGIN;

INSERT INTO permission_catalog(permission_code,domain,risk_class,sod_class) VALUES
 ('ACCOUNTING.SETTINGS.WORKFLOW.VIEW','AI_ACCOUNTING','LOW','READ'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.CREATE','AI_ACCOUNTING','HIGH','ACCOUNTING_SETTINGS_DRAFT'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.SUBMIT','AI_ACCOUNTING','HIGH','ACCOUNTING_SETTINGS_SUBMIT'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.REVIEW','AI_ACCOUNTING','HIGH','ACCOUNTING_SETTINGS_REVIEW'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.APPROVE','AI_ACCOUNTING','CRITICAL','ACCOUNTING_SETTINGS_APPROVE'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.ACTIVATE','AI_ACCOUNTING','CRITICAL','ACCOUNTING_SETTINGS_ACTIVATE')
ON CONFLICT(permission_code) DO UPDATE SET active=true,domain=EXCLUDED.domain,risk_class=EXCLUDED.risk_class,
 sod_class=EXCLUDED.sod_class,version=permission_catalog.version+1,effective_to=NULL;

INSERT INTO runtime_human_permission_authority(permission_code,authority_class) VALUES
 ('ACCOUNTING.SETTINGS.WORKFLOW.VIEW','READ'),('ACCOUNTING.SETTINGS.WORKFLOW.CREATE','DRAFT'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.SUBMIT','SUBMIT'),('ACCOUNTING.SETTINGS.WORKFLOW.REVIEW','REVIEW'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.APPROVE','APPROVE'),('ACCOUNTING.SETTINGS.WORKFLOW.ACTIVATE','POST')
ON CONFLICT(permission_code) DO UPDATE SET authority_class=EXCLUDED.authority_class;

-- Workflow VIEW is additive to exactly one lifecycle authority, so each role can
-- inspect the evidence it acts on without combining two lifecycle stages.
ALTER TABLE runtime_human_additive_permission_authority
 DROP CONSTRAINT runtime_human_additive_permission_authority_check;
ALTER TABLE runtime_human_additive_permission_authority
 ADD CONSTRAINT runtime_human_additive_permission_authority_check CHECK(
  (permission_code='ATTACHMENT.CREATE' AND authority_class IN('DRAFT','PAYMENT','RECEIPT','ADJUSTMENT'))
  OR(permission_code='ACCOUNTING.SETTINGS.WORKFLOW.VIEW' AND authority_class IN('DRAFT','SUBMIT','REVIEW','APPROVE','POST'))
 );
INSERT INTO runtime_human_additive_permission_authority(permission_code,authority_class) VALUES
 ('ACCOUNTING.SETTINGS.WORKFLOW.VIEW','DRAFT'),('ACCOUNTING.SETTINGS.WORKFLOW.VIEW','SUBMIT'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.VIEW','REVIEW'),('ACCOUNTING.SETTINGS.WORKFLOW.VIEW','APPROVE'),
 ('ACCOUNTING.SETTINGS.WORKFLOW.VIEW','POST');

CREATE TABLE accounting_settings_workflow(
 accounting_settings_workflow_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 tenant_id uuid NOT NULL,entity_id uuid NOT NULL,period_id uuid NOT NULL,
 version bigint NOT NULL CHECK(version>0),status text NOT NULL DEFAULT 'DRAFT'
   CHECK(status IN('DRAFT','SUBMITTED','REVIEWED','APPROVED','ACTIVE','SUPERSEDED')),
 revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),
 child_setting_snapshot_ids jsonb NOT NULL CHECK(jsonb_typeof(child_setting_snapshot_ids)='object'),
 canonical_parent_snapshot jsonb NOT NULL CHECK(jsonb_typeof(canonical_parent_snapshot)='object'),
 canonical_parent_hash text NOT NULL CHECK(canonical_parent_hash~'^sha256:[0-9a-f]{64}$'),
 legacy_parent_setting_snapshot_id uuid,
 created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 submitted_by text,submitted_at timestamptz,reviewed_by text,reviewed_at timestamptz,
 approved_by text,approved_at timestamptz,activated_by text,activated_at timestamptz,
 superseded_by_workflow_id uuid,superseded_at timestamptz,
 UNIQUE(tenant_id,entity_id,version),UNIQUE(tenant_id,accounting_settings_workflow_id),UNIQUE(tenant_id,entity_id,accounting_settings_workflow_id),
 FOREIGN KEY(tenant_id,entity_id,period_id) REFERENCES accounting_period(tenant_id,entity_id,period_id),
 FOREIGN KEY(tenant_id,legacy_parent_setting_snapshot_id) REFERENCES setting_snapshot(tenant_id,setting_snapshot_id),
 FOREIGN KEY(tenant_id,entity_id,superseded_by_workflow_id) REFERENCES accounting_settings_workflow(tenant_id,entity_id,accounting_settings_workflow_id),
 CHECK(canonical_parent_hash=refs_jsonb_hash(canonical_parent_snapshot)),
 CHECK((submitted_by IS NULL)=(submitted_at IS NULL) AND(reviewed_by IS NULL)=(reviewed_at IS NULL)
   AND(approved_by IS NULL)=(approved_at IS NULL) AND(activated_by IS NULL)=(activated_at IS NULL)),
 CHECK(submitted_by IS NULL OR submitted_by<>created_by),
 CHECK(reviewed_by IS NULL OR reviewed_by<>ALL(ARRAY[created_by,submitted_by])),
 CHECK(approved_by IS NULL OR approved_by<>ALL(ARRAY[created_by,submitted_by,reviewed_by])),
 CHECK(activated_by IS NULL OR activated_by<>ALL(ARRAY[created_by,submitted_by,reviewed_by,approved_by])),
 CHECK((status='DRAFT' AND revision=0 AND submitted_by IS NULL AND reviewed_by IS NULL AND approved_by IS NULL AND activated_by IS NULL AND legacy_parent_setting_snapshot_id IS NULL)
   OR(status='SUBMITTED' AND revision=1 AND submitted_by IS NOT NULL AND reviewed_by IS NULL AND approved_by IS NULL AND activated_by IS NULL AND legacy_parent_setting_snapshot_id IS NULL)
   OR(status='REVIEWED' AND revision=2 AND submitted_by IS NOT NULL AND reviewed_by IS NOT NULL AND approved_by IS NULL AND activated_by IS NULL AND legacy_parent_setting_snapshot_id IS NULL)
   OR(status='APPROVED' AND revision=3 AND submitted_by IS NOT NULL AND reviewed_by IS NOT NULL AND approved_by IS NOT NULL AND activated_by IS NULL AND legacy_parent_setting_snapshot_id IS NULL)
   OR(status='ACTIVE' AND revision=4 AND submitted_by IS NOT NULL AND reviewed_by IS NOT NULL AND approved_by IS NOT NULL AND activated_by IS NOT NULL AND legacy_parent_setting_snapshot_id IS NOT NULL)
   OR(status='SUPERSEDED' AND revision=5 AND submitted_by IS NOT NULL AND reviewed_by IS NOT NULL AND approved_by IS NOT NULL AND activated_by IS NOT NULL AND legacy_parent_setting_snapshot_id IS NOT NULL)),
 CHECK((status='SUPERSEDED' AND superseded_by_workflow_id IS NOT NULL AND superseded_by_workflow_id<>accounting_settings_workflow_id AND superseded_at IS NOT NULL)
   OR(status<>'SUPERSEDED' AND superseded_by_workflow_id IS NULL AND superseded_at IS NULL))
);
CREATE UNIQUE INDEX accounting_settings_one_active_entity_uq ON accounting_settings_workflow(tenant_id,entity_id) WHERE status='ACTIVE';
CREATE INDEX accounting_settings_workflow_register_idx ON accounting_settings_workflow(tenant_id,entity_id,created_at DESC,accounting_settings_workflow_id DESC);

CREATE TABLE accounting_settings_workflow_history(
 accounting_settings_workflow_history_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 accounting_settings_workflow_id uuid NOT NULL,tenant_id uuid NOT NULL,from_status text,to_status text NOT NULL,
 revision bigint NOT NULL CHECK(revision>=0),actor_id text NOT NULL,reason text NOT NULL,
 previous_event_hash text CHECK(previous_event_hash~'^sha256:[0-9a-f]{64}$'),event_hash text NOT NULL CHECK(event_hash~'^sha256:[0-9a-f]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK((revision=0)=(previous_event_hash IS NULL)),
 CHECK(length(actor_id) BETWEEN 1 AND 300 AND actor_id=btrim(actor_id) AND actor_id!~'[[:cntrl:]]'),
 CHECK(length(reason) BETWEEN 8 AND 2000 AND reason=btrim(reason) AND reason!~'[[:cntrl:]]'),
 CHECK((revision=0 AND from_status IS NULL AND to_status='DRAFT')
   OR(revision=1 AND from_status='DRAFT' AND to_status='SUBMITTED')
   OR(revision=2 AND from_status='SUBMITTED' AND to_status='REVIEWED')
   OR(revision=3 AND from_status='REVIEWED' AND to_status='APPROVED')
   OR(revision=4 AND from_status='APPROVED' AND to_status='ACTIVE')
   OR(revision=5 AND from_status='ACTIVE' AND to_status='SUPERSEDED')),
 UNIQUE(accounting_settings_workflow_id,revision),
 FOREIGN KEY(tenant_id,accounting_settings_workflow_id) REFERENCES accounting_settings_workflow(tenant_id,accounting_settings_workflow_id)
);
CREATE TABLE accounting_settings_workflow_gate(
 backend_pid integer NOT NULL,transaction_id bigint NOT NULL,tenant_id uuid NOT NULL,accounting_settings_workflow_id uuid NOT NULL,
 operation text NOT NULL CHECK(operation IN('SUBMITTED','REVIEWED','APPROVED','ACTIVE','SUPERSEDED','PARENT_RETIRE')),
 PRIMARY KEY(backend_pid,transaction_id,tenant_id,accounting_settings_workflow_id,operation)
);

ALTER TABLE accounting_settings_workflow ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounting_settings_workflow_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY accounting_settings_workflow_scope ON accounting_settings_workflow USING(tenant_id=refs_current_tenant() AND refs_entity_allowed(entity_id));
CREATE POLICY accounting_settings_workflow_history_scope ON accounting_settings_workflow_history USING(EXISTS(
 SELECT 1 FROM accounting_settings_workflow w WHERE w.tenant_id=refs_current_tenant() AND w.accounting_settings_workflow_id=accounting_settings_workflow_history.accounting_settings_workflow_id AND refs_entity_allowed(w.entity_id)));
REVOKE ALL ON accounting_settings_workflow,accounting_settings_workflow_history,accounting_settings_workflow_gate FROM PUBLIC,refs_app;

CREATE FUNCTION refs_protect_workflow_owned_accounting_settings_parent() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF OLD.status='APPROVED' AND TG_OP='UPDATE' AND NEW.status='RETIRED'
   AND EXISTS(SELECT 1 FROM accounting_settings_workflow w JOIN accounting_period p ON p.tenant_id=w.tenant_id AND p.entity_id=w.entity_id AND p.period_id=w.period_id WHERE w.tenant_id=OLD.tenant_id AND w.entity_id=OLD.entity_id AND w.status IN('ACTIVE','SUPERSEDED') AND EXISTS(SELECT 1 FROM jsonb_each_text(w.child_setting_snapshot_ids) child WHERE child.value=OLD.setting_snapshot_id::text) AND (NEW.effective_to IS NULL OR NEW.effective_to<=p.ends_on::timestamptz)) THEN
  RAISE EXCEPTION 'Active accounting settings child must cover its bound period' USING ERRCODE='42501';
 END IF;
 IF OLD.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND OLD.status='APPROVED'
   AND (TG_OP='DELETE' OR (TG_OP='UPDATE' AND NEW.status='RETIRED'))
   AND EXISTS(SELECT 1 FROM accounting_settings_workflow w WHERE w.tenant_id=OLD.tenant_id AND w.entity_id=OLD.entity_id AND w.status='ACTIVE' AND w.legacy_parent_setting_snapshot_id=OLD.setting_snapshot_id)
   AND NOT EXISTS(SELECT 1 FROM accounting_settings_workflow_gate g JOIN accounting_settings_workflow w ON w.tenant_id=g.tenant_id AND w.accounting_settings_workflow_id=g.accounting_settings_workflow_id WHERE g.backend_pid=pg_backend_pid() AND g.transaction_id=txid_current() AND g.tenant_id=OLD.tenant_id AND g.operation='PARENT_RETIRE' AND w.status='ACTIVE' AND w.legacy_parent_setting_snapshot_id=OLD.setting_snapshot_id) THEN
  RAISE EXCEPTION 'Active accounting settings parent retirement requires forward workflow activation' USING ERRCODE='42501';
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;$$;
CREATE TRIGGER setting_snapshot_accounting_settings_parent_guard BEFORE UPDATE OR DELETE ON setting_snapshot FOR EACH ROW EXECUTE FUNCTION refs_protect_workflow_owned_accounting_settings_parent();
CREATE FUNCTION refs_protect_accounting_settings_workflow() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Accounting settings workflow is retained evidence' USING ERRCODE='55000';END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting_settings_workflow_gate g WHERE g.backend_pid=pg_backend_pid() AND g.transaction_id=txid_current()
   AND g.tenant_id=OLD.tenant_id AND g.accounting_settings_workflow_id=OLD.accounting_settings_workflow_id AND g.operation=NEW.status) THEN
  RAISE EXCEPTION 'Accounting settings transition must use the authoritative command' USING ERRCODE='42501';END IF;
 IF (to_jsonb(NEW)-ARRAY['status','revision','submitted_by','submitted_at','reviewed_by','reviewed_at','approved_by','approved_at','activated_by','activated_at','legacy_parent_setting_snapshot_id','superseded_by_workflow_id','superseded_at']::text[])
   IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','submitted_by','submitted_at','reviewed_by','reviewed_at','approved_by','approved_at','activated_by','activated_at','legacy_parent_setting_snapshot_id','superseded_by_workflow_id','superseded_at']::text[])
   OR NEW.revision<>OLD.revision+1 OR NOT((OLD.status='DRAFT' AND NEW.status='SUBMITTED')OR(OLD.status='SUBMITTED' AND NEW.status='REVIEWED')
   OR(OLD.status='REVIEWED' AND NEW.status='APPROVED')OR(OLD.status='APPROVED' AND NEW.status='ACTIVE')OR(OLD.status='ACTIVE' AND NEW.status='SUPERSEDED')) THEN
  RAISE EXCEPTION 'Invalid accounting settings workflow mutation' USING ERRCODE='55000';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER accounting_settings_workflow_protect BEFORE UPDATE OR DELETE ON accounting_settings_workflow FOR EACH ROW EXECUTE FUNCTION refs_protect_accounting_settings_workflow();
CREATE TRIGGER accounting_settings_workflow_history_append_only BEFORE UPDATE OR DELETE ON accounting_settings_workflow_history FOR EACH ROW EXECUTE FUNCTION reject_mutation();

-- Private selected-bundle validator used before workflow state is retained.
CREATE FUNCTION refs_validate_accounting_settings_selected_bundle(
  p_tenant uuid,p_entity uuid,p_period uuid,p_parent jsonb,p_ids jsonb,p_allow_retired boolean
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE period_row accounting_period;entity_row entity;parent_row setting_snapshot;child_row setting_snapshot;
  child jsonb;result jsonb:='[]'::jsonb;child_key text;child_family text;
  expected_keys constant text[]:=ARRAY[
    'schema_version','company_code','period_id','period_code','period_start','period_end','currency',
    'coa','vendor_treatment','project_property_cost_code','period_close_policy','tax','intercompany','materiality','approval_thresholds','report_mapping','loan_capitalization_policy'
  ];
  child_keys constant text[]:=ARRAY['coa','vendor_treatment','project_property_cost_code','period_close_policy','tax','intercompany','materiality','approval_thresholds','report_mapping','loan_capitalization_policy'];
  child_families constant text[]:=ARRAY[
    'AI_ACCOUNTING_COA_V1','AI_ACCOUNTING_VENDOR_TREATMENT_V1','AI_ACCOUNTING_PROJECT_PROPERTY_COST_CODE_V1','AI_ACCOUNTING_PERIOD_CLOSE_POLICY_V1',
    'AI_ACCOUNTING_TAX_V1','AI_ACCOUNTING_INTERCOMPANY_V1','AI_ACCOUNTING_MATERIALITY_V1','AI_ACCOUNTING_APPROVAL_THRESHOLDS_V1','AI_ACCOUNTING_REPORT_MAPPING_V1','AI_ACCOUNTING_LOAN_CAPITALIZATION_POLICY_V1'
  ];
BEGIN
  IF p_allow_retired IS NULL OR jsonb_typeof(p_parent)<>'object'
     OR ARRAY(SELECT jsonb_object_keys(p_parent) ORDER BY 1)<>ARRAY(SELECT unnest(expected_keys) ORDER BY 1)
     OR jsonb_typeof(p_ids)<>'object'
     OR ARRAY(SELECT jsonb_object_keys(p_ids) ORDER BY 1)<>ARRAY(SELECT unnest(child_keys) ORDER BY 1)
     OR EXISTS(SELECT 1 FROM jsonb_each_text(p_ids) x WHERE x.value!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') THEN
    RAISE EXCEPTION 'Selected accounting settings bundle is malformed' USING ERRCODE='23514';
  END IF;
  SELECT * INTO period_row FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period;
  SELECT * INTO entity_row FROM entity WHERE tenant_id=p_tenant AND entity_id=p_entity;
  IF period_row.period_id IS NULL OR entity_row.entity_id IS NULL OR (NOT p_allow_retired AND NOT entity_row.active) THEN RAISE EXCEPTION 'Accounting settings entity or period was not found or active' USING ERRCODE='P0002';END IF;
  IF NOT p_allow_retired AND (period_row.ledger_code<>'PRIMARY' OR EXISTS(SELECT 1 FROM accounting_period other WHERE other.tenant_id=p_tenant AND other.entity_id=p_entity AND other.ledger_code='PRIMARY' AND other.period_id<>period_row.period_id AND daterange(other.starts_on,other.ends_on,'[]')&&daterange(period_row.starts_on,period_row.ends_on,'[]'))) THEN RAISE EXCEPTION 'Selected accounting settings bundle requires one non-overlapping PRIMARY period' USING ERRCODE='23514';END IF;
  IF p_parent->>'schema_version'<>'AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_SNAPSHOT_V1' OR p_parent->>'company_code' !~ '^[A-Z0-9][A-Z0-9_:-]{0,63}$' OR p_parent->>'period_id'<>p_period::text OR p_parent->>'period_code'<>period_row.period_code OR p_parent->>'period_start'<>period_row.starts_on::text OR p_parent->>'period_end'<>period_row.ends_on::text OR p_parent->>'currency' !~ '^[A-Z]{3}$' OR (NOT p_allow_retired AND (p_parent->>'company_code'<>entity_row.entity_code OR p_parent->>'currency'<>entity_row.base_currency)) THEN RAISE EXCEPTION 'Selected accounting settings parent envelope is malformed or cross-scope' USING ERRCODE='23514';END IF;
  parent_row.snapshot:=p_parent;
  FOR child_key,child_family IN SELECT * FROM unnest(child_keys,child_families) LOOP
    child:=parent_row.snapshot->child_key;
    IF jsonb_typeof(child)<>'object'
       OR ARRAY(SELECT jsonb_object_keys(child) ORDER BY 1)<>ARRAY['setting_snapshot_id','snapshot_hash','version']
       OR child->>'setting_snapshot_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR child->>'snapshot_hash' !~ '^sha256:[0-9a-f]{64}$'
       OR child->>'version' !~ '^[1-9][0-9]*$' OR p_ids->>child_key IS DISTINCT FROM child->>'setting_snapshot_id' THEN
      RAISE EXCEPTION 'Approved AI child settings reference is malformed' USING ERRCODE='23514';
    END IF;
    SELECT * INTO child_row FROM setting_snapshot
     WHERE tenant_id=p_tenant AND entity_id=p_entity AND setting_snapshot_id=(child->>'setting_snapshot_id')::uuid
       AND family=child_family AND scope_type='ENTITY' AND scope_key=p_entity::text AND ((NOT p_allow_retired AND status='APPROVED') OR (p_allow_retired AND status IN('APPROVED','RETIRED')))
       AND effective_from<=period_row.starts_on::timestamptz AND (effective_to IS NULL OR effective_to>period_row.ends_on::timestamptz);
    IF NOT FOUND OR child_row.version<>(child->>'version')::bigint OR child_row.snapshot_hash<>child->>'snapshot_hash'
       OR child_row.snapshot_hash<>refs_jsonb_hash(child_row.snapshot) THEN
      RAISE EXCEPTION 'Approved AI child settings snapshot is missing, stale, or changed' USING ERRCODE='23514';
    END IF;
    IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot) ORDER BY 1)<>ARRAY['schema_version','settings']
       OR jsonb_typeof(child_row.snapshot->'settings')<>'object' OR child_row.snapshot->>'schema_version'<>child_family THEN
      RAISE EXCEPTION 'Approved AI child settings schema is unsupported or not closed' USING ERRCODE='23514';
    END IF;
    IF NOT refs_wbs_ai_settings_dates_are_valid(child_row.snapshot->'settings') THEN
      RAISE EXCEPTION 'Approved AI child settings contain an invalid calendar date' USING ERRCODE='23514';
    END IF;
    IF child_key='coa' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['accounts','currency']
         OR child_row.snapshot#>>'{settings,currency}'<>parent_row.snapshot->>'currency'
         OR jsonb_typeof(child_row.snapshot#>'{settings,accounts}')<>'array'
           OR (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}'))<24
           OR (SELECT count(DISTINCT account->>'account_code') FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') account)<>(SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}'))
           OR EXISTS(SELECT 1 FROM unnest(ARRAY['ACCUMULATED_AMORTIZATION','ACCUMULATED_DEPRECIATION','ACCRUED_LIABILITY','AP','AR','CASH','CWIP','CUSTOMER_DEPOSIT_LIABILITY','DEFERRED_REVENUE','EQUITY','ESCROW','EXPENSE','FIXED_ASSET','INTERCOMPANY_CLEARING','INTERCOMPANY_DUE_FROM','INTERCOMPANY_DUE_TO','INTERCOMPANY_ELIMINATION','INTEREST','LOAN','PREPAID','RETAINED_EARNINGS','REVENUE','SECURITY_DEPOSIT_ASSET','TAX_PAYABLE']) required(role) WHERE (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') a WHERE a->>'role'=required.role AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text))<>1)
          OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') account WHERE jsonb_typeof(account)<>'object' OR ARRAY(SELECT jsonb_object_keys(account) ORDER BY 1)<>ARRAY['account_class','account_code','account_type','dimension_requirements','effective_from','effective_to','posting_allowed','role','status'] OR account->>'account_code' !~ '^[A-Z0-9._-]{1,64}$' OR account->>'account_class' NOT IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE') OR account->>'account_type'='' OR jsonb_typeof(account->'dimension_requirements')<>'array' OR jsonb_typeof(account->'posting_allowed')<>'boolean' OR account->>'status' NOT IN ('ACTIVE','INACTIVE') OR account->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (account->>'effective_to' IS NOT NULL AND account->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$') OR (account->>'effective_to' IS NOT NULL AND account->>'effective_from'>account->>'effective_to') OR (account->>'role' IN ('AP','ACCRUED_LIABILITY','LOAN','DEFERRED_REVENUE','TAX_PAYABLE','CUSTOMER_DEPOSIT_LIABILITY','INTERCOMPANY_DUE_TO') AND account->>'account_class'<>'LIABILITY') OR (account->>'role' IN ('AR','CASH','CWIP','ESCROW','PREPAID','FIXED_ASSET','INTERCOMPANY_DUE_FROM','SECURITY_DEPOSIT_ASSET','ACCUMULATED_DEPRECIATION','ACCUMULATED_AMORTIZATION') AND account->>'account_class'<>'ASSET') OR (account->>'role' IN ('EXPENSE','INTEREST') AND account->>'account_class'<>'EXPENSE') OR (account->>'role'='REVENUE' AND account->>'account_class'<>'REVENUE') OR (account->>'role' IN ('EQUITY','RETAINED_EARNINGS','INTERCOMPANY_ELIMINATION') AND account->>'account_class'<>'EQUITY') OR (account->>'role'='INTERCOMPANY_CLEARING' AND account->>'account_class' NOT IN ('ASSET','LIABILITY'))) THEN RAISE EXCEPTION 'Approved AI COA settings are incomplete' USING ERRCODE='23514'; END IF;
    ELSIF child_key='vendor_treatment' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['default_treatment','vendor_rules']
         OR child_row.snapshot#>>'{settings,default_treatment}'<>'BLOCKED'
         OR jsonb_typeof(child_row.snapshot#>'{settings,vendor_rules}')<>'array'
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v WHERE jsonb_typeof(v)<>'object' OR ARRAY(SELECT jsonb_object_keys(v) ORDER BY 1)<>ARRAY['aliases','contract_keys','duplicate_normalization','effective_from','effective_to','payment_terms_days','recurring','rule_id','service_keys','source_requirements','treatment','vendor_ref'] OR v->>'vendor_ref'='' OR v->>'rule_id'='' OR v->>'treatment' NOT IN ('EXPENSE','PREPAID','ACCRUAL','CWIP','LOAN','REVENUE','DEPOSIT','INTERCOMPANY','REIMBURSEMENT') OR jsonb_typeof(v->'aliases')<>'array' OR jsonb_typeof(v->'contract_keys')<>'array' OR jsonb_typeof(v->'service_keys')<>'array' OR jsonb_typeof(v->'source_requirements')<>'array' OR jsonb_typeof(v->'recurring')<>'boolean' OR jsonb_typeof(v->'duplicate_normalization')<>'boolean' OR NOT (CASE WHEN jsonb_typeof(v->'payment_terms_days')='number' THEN (v->>'payment_terms_days')::numeric=trunc((v->>'payment_terms_days')::numeric) AND (v->>'payment_terms_days')::numeric BETWEEN 0 AND 9999 ELSE false END) OR v->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (v->>'effective_to' IS NOT NULL AND v->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$'))
         OR (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}'))<>(SELECT count(DISTINCT v->>'vendor_ref') FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v) THEN RAISE EXCEPTION 'Approved vendor treatment settings are incomplete or ambiguous' USING ERRCODE='23514'; END IF;
    ELSIF child_key='project_property_cost_code' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['default_capitalization_treatment','dimension_rules'] OR child_row.snapshot#>>'{settings,default_capitalization_treatment}'<>'BLOCKED' OR jsonb_typeof(child_row.snapshot#>'{settings,dimension_rules}')<>'array'
