rop_window_days}')::numeric BETWEEN 1 AND 9007199254740991 ELSE false END) OR NOT (CASE WHEN jsonb_typeof(child_row.snapshot#>'{settings,vendor_frequency_count}')='number' THEN (child_row.snapshot#>>'{settings,vendor_frequency_count}')::numeric=trunc((child_row.snapshot#>>'{settings,vendor_frequency_count}')::numeric) AND (child_row.snapshot#>>'{settings,vendor_frequency_count}')::numeric BETWEEN 1 AND 9007199254740991 ELSE false END) OR NOT (CASE WHEN jsonb_typeof(child_row.snapshot#>'{settings,vendor_frequency_window_days}')='number' THEN (child_row.snapshot#>>'{settings,vendor_frequency_window_days}')::numeric=trunc((child_row.snapshot#>>'{settings,vendor_frequency_window_days}')::numeric) AND (child_row.snapshot#>>'{settings,vendor_frequency_window_days}')::numeric BETWEEN 1 AND 9007199254740991 ELSE false END) OR child_row.snapshot#>>'{settings,effective_from}' !~ '^\d{4}-\d{2}-\d{2}$' OR (child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_to}' !~ '^\d{4}-\d{2}-\d{2}$') THEN RAISE EXCEPTION 'Approved materiality settings are incomplete' USING ERRCODE='23514'; END IF;
