         OR child_row.snapshot#>>'{settings,materiality_amount}' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$'
         OR jsonb_typeof(child_row.snapshot#>'{settings,qualifying_combinations}')<>'array' OR jsonb_array_length(child_row.snapshot#>'{settings,qualifying_combinations}')=0
         OR jsonb_typeof(child_row.snapshot#>'{settings,required_evidence}')<>'array' OR jsonb_array_length(child_row.snapshot#>'{settings,required_evidence}')=0
         OR child_row.snapshot#>>'{settings,effective_from}' !~ '^\d{4}-\d{2}-\d{2}$'
         OR (child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_to}' !~ '^\d{4}-\d{2}-\d{2}$')
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,qualifying_combinations}') q WHERE jsonb_typeof(q)<>'object' OR ARRAY(SELECT jsonb_object_keys(q) ORDER BY 1)<>ARRAY['asset_ref','effective_from','effective_to','project_ref','property_ref'] OR q->>'asset_ref' IS NOT NULL OR (q->>'project_ref' IS NULL AND q->>'property_ref' IS NULL) OR q->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (q->>'effective_to' IS NOT NULL AND q->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$') OR NOT EXISTS(SELECT 1 FROM setting_snapshot dimension_row JOIN LATERAL jsonb_array_elements(dimension_row.snapshot#>'{settings,dimension_rules}') d ON true WHERE dimension_row.tenant_id=p_tenant AND dimension_row.entity_id=p_entity AND dimension_row.setting_snapshot_id=(parent_row.snapshot#>>'{project_property_cost_code,setting_snapshot_id}')::uuid AND d->>'status'='ACTIVE' AND d->>'capitalization_treatment'='CWIP' AND d->>'ownership_requirement'<>'FORBIDDEN' AND d->>'project_ref' IS NOT DISTINCT FROM q->>'project_ref' AND d->>'property_ref' IS NOT DISTINCT FROM q->>'property_ref' AND (d->>'completion_date' IS NULL OR d->>'completion_date'>=period_row.starts_on::text) AND (d->>'pis_date' IS NULL OR d->>'pis_date'>=period_row.starts_on::text))) THEN RAISE EXCEPTION 'Approved loan capitalization policy is incomplete' USING ERRCODE='23514'; END IF;
      IF jsonb_typeof(child_row.snapshot#>'{settings,materiality_amount}')<>'string' THEN RAISE EXCEPTION 'Approved loan materiality MONEY4 value must be a JSON string' USING ERRCODE='23514'; END IF;
    END IF;
    IF child_key='report_mapping' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['account_mappings','currency']
         OR child_row.snapshot#>>'{settings,currency}'<>parent_row.snapshot->>'currency'
         OR jsonb_typeof(child_row.snapshot#>'{settings,account_mappings}')<>'array'
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE jsonb_typeof(m)<>'object' OR ARRAY(SELECT jsonb_object_keys(m) ORDER BY 1)<>ARRAY['account_code','account_role','cash_flow_class','contra','effective_from','effective_to','normal_balance','report_row_code','statement'] OR m->>'account_code' !~ '^[A-Z0-9._-]{1,64}$' OR m->>'account_role'='' OR m->>'statement' NOT IN ('BS','IS') OR m->>'normal_balance' NOT IN ('DEBIT','CREDIT') OR jsonb_typeof(m->'contra')<>'boolean' OR m->>'cash_flow_class' NOT IN ('OPERATING','INVESTING','FINANCING','NON_CASH') OR m->>'report_row_code'='' OR m->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (m->>'effective_to' IS NOT NULL AND m->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$') OR (m->>'effective_to' IS NOT NULL AND m->>'effective_from'>m->>'effective_to')) THEN RAISE EXCEPTION 'Approved report mapping is incomplete or ambiguous' USING ERRCODE='23514'; END IF;
      IF (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE m->>'effective_from'<=period_row.starts_on::text AND (m->>'effective_to' IS NULL OR m->>'effective_to'>=period_row.ends_on::text))<>(SELECT count(*) FROM setting_snapshot coa_row JOIN LATERAL jsonb_array_elements(coa_row.snapshot#>'{settings,accounts}') a ON true WHERE coa_row.tenant_id=p_tenant AND coa_row.entity_id=p_entity AND coa_row.setting_snapshot_id=(parent_row.snapshot#>>'{coa,setting_snapshot_id}')::uuid AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text)) OR EXISTS(SELECT 1 FROM setting_snapshot coa_row JOIN LATERAL jsonb_array_elements(coa_row.snapshot#>'{settings,accounts}') a ON true WHERE coa_row.tenant_id=p_tenant AND coa_row.entity_id=p_entity AND coa_row.setting_snapshot_id=(parent_row.snapshot#>>'{coa,setting_snapshot_id}')::uuid AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text) AND (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE m->>'account_code'=a->>'account_code' AND m->>'account_role'=a->>'role' AND m->>'effective_from'<=period_row.starts_on::text AND (m->>'effective_to' IS NULL OR m->>'effective_to'>=period_row.ends_on::text))<>1) OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE m->>'effective_from'<=period_row.starts_on::text AND (m->>'effective_to' IS NULL OR m->>'effective_to'>=period_row.ends_on::text) AND NOT EXISTS(SELECT 1 FROM setting_snapshot coa_row JOIN LATERAL jsonb_array_elements(coa_row.snapshot#>'{settings,accounts}') a ON true WHERE coa_row.tenant_id=p_tenant AND coa_row.entity_id=p_entity AND coa_row.setting_snapshot_id=(parent_row.snapshot#>>'{coa,setting_snapshot_id}')::uuid AND a->>'account_code'=m->>'account_code' AND a->>'role'=m->>'account_role' AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text))) THEN RAISE EXCEPTION 'Approved report mapping does not bind the approved COA' USING ERRCODE='23514'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE (m->>'account_role' IN ('AP','ACCRUED_LIABILITY','LOAN','DEFERRED_REVENUE','TAX_PAYABLE','CUSTOMER_DEPOSIT_LIABILITY','INTERCOMPANY_DUE_TO') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'false')) OR (m->>'account_role' IN ('AR','CASH','CWIP','ESCROW','PREPAID','FIXED_ASSET','INTERCOMPANY_DUE_FROM','SECURITY_DEPOSIT_ASSET') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'DEBIT' OR m->>'contra'<>'false')) OR (m->>'account_role' IN ('ACCUMULATED_DEPRECIATION','ACCUMULATED_AMORTIZATION') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'true')) OR (m->>'account_role' IN ('EXPENSE','INTEREST') AND (m->>'statement'<>'IS' OR m->>'normal_balance'<>'DEBIT' OR m->>'contra'<>'false')) OR (m->>'account_role'='REVENUE' AND (m->>'statement'<>'IS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'false')) OR (m->>'account_role' IN ('EQUITY','RETAINED_EARNINGS','INTERCOMPANY_ELIMINATION') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'false'))) THEN RAISE EXCEPTION 'Approved report mapping violates COA role semantics' USING ERRCODE='23514'; END IF;
      IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') AS m
        JOIN setting_snapshot AS coa_row
          ON coa_row.tenant_id=p_tenant
         AND coa_row.entity_id=p_entity
         AND coa_row.setting_snapshot_id=(parent_row.snapshot#>>'{coa,setting_snapshot_id}')::uuid
        JOIN LATERAL jsonb_array_elements(coa_row.snapshot#>'{settings,accounts}') AS account
          ON account->>'account_code'=m->>'account_code'
         AND account->>'role'=m->>'account_role'
        WHERE m->>'account_role'='INTERCOMPANY_CLEARING'
          AND m->>'effective_from'<=period_row.starts_on::text
          AND (m->>'effective_to' IS NULL OR m->>'effective_to'>=period_row.ends_on::text)
          AND account->>'status'='ACTIVE'
          AND account->>'posting_allowed'='true'
          AND account->>'effective_from'<=period_row.starts_on::text
          AND (account->>'effective_to' IS NULL OR account->>'effective_to'>=period_row.ends_on::text)
          AND (
            m->>'statement'<>'BS'
            OR m->>'contra'<>'false'
            OR (account->>'account_class'='ASSET' AND m->>'normal_balance'<>'DEBIT')
            OR (account->>'account_class'='LIABILITY' AND m->>'normal_balance'<>'CREDIT')
            OR account->>'account_class' NOT IN ('ASSET','LIABILITY')
          )
      ) THEN
        RAISE EXCEPTION 'Approved intercompany clearing report mapping violates COA class semantics' USING ERRCODE='23514';
      END IF;
    END IF;
    IF CASE child_key
      WHEN 'vendor_treatment' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v WHERE v->>'effective_to' IS NOT NULL AND v->>'effective_from'>v->>'effective_to')
      WHEN 'project_property_cost_code' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,dimension_rules}') d WHERE d->>'effective_to' IS NOT NULL AND d->>'effective_from'>d->>'effective_to')
      WHEN 'tax' THEN (child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_from}'>child_row.snapshot#>>'{settings,effective_to}') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,tax_codes}') t WHERE t->>'effective_to' IS NOT NULL AND t->>'effective_from'>t->>'effective_to')
      WHEN 'intercompany' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,entities}') i WHERE i->>'effective_to' IS NOT NULL AND i->>'effective_from'>i->>'effective_to')
      WHEN 'materiality' THEN child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_from}'>child_row.snapshot#>>'{settings,effective_to}'
      WHEN 'approval_thresholds' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,approval_levels}') a WHERE a->>'effective_to' IS NOT NULL AND a->>'effective_from'>a->>'effective_to') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,classification_thresholds}') c WHERE c->>'effective_to' IS NOT NULL AND c->>'effective_from'>c->>'effective_to')
      WHEN 'loan_capitalization_policy' THEN (child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_from}'>child_row.snapshot#>>'{settings,effective_to}') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,qualifying_combinations}') q WHERE q->>'effective_to' IS NOT NULL AND q->>'effective_from'>q->>'effective_to')
      ELSE false END THEN RAISE EXCEPTION 'Approved AI settings contain a reversed effective range' USING ERRCODE='23514'; END IF;
    IF CASE child_key
      WHEN 'coa' THEN jsonb_typeof(child_row.snapshot#>'{settings,currency}')<>'string' OR btrim(child_row.snapshot#>>'{settings,currency}')='' OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') a CROSS JOIN LATERAL unnest(ARRAY['account_code','account_class','account_type','role','status','effective_from']) required_key(key) WHERE jsonb_typeof(a->key)<>'string' OR btrim(a->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') a WHERE a->'effective_to' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(a->'effective_to')<>'string' OR btrim(a->>'effective_to')=''))
      WHEN 'vendor_treatment' THEN jsonb_typeof(child_row.snapshot#>'{settings,default_treatment}')<>'string' OR btrim(child_row.snapshot#>>'{settings,default_treatment}')='' OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v CROSS JOIN LATERAL unnest(ARRAY['rule_id','vendor_ref','treatment','effective_from']) required_key(key) WHERE jsonb_typeof(v->key)<>'string' OR btrim(v->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v WHERE v->'effective_to' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(v->'effective_to')<>'string' OR btrim(v->>'effective_to')=''))
      WHEN 'project_property_cost_code' THEN jsonb_typeof(child_row.snapshot#>'{settings,default_capitalization_treatment}')<>'string' OR btrim(child_row.snapshot#>>'{settings,default_capitalization_treatment}')='' OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,dimension_rules}') d CROSS JOIN LATERAL unnest(ARRAY['rule_id','capitalization_treatment','cwip_account_role','status','scope_level','member_requirement','ownership_requirement','effective_from']) required_key(key) WHERE jsonb_typeof(d->key)<>'string' OR btrim(d->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,dimension_rules}') d CROSS JOIN LATERAL unnest(ARRAY['effective_to','cost_code_ref','project_ref','property_ref','member_ref','completion_date','pis_date']) required_key(key) WHERE d->key IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(d->key)<>'string' OR btrim(d->>key)=''))
      WHEN 'period_close_policy' THEN EXISTS(SELECT 1 FROM unnest(ARRAY['period_id','period_code','period_start','period_end','period_status','cutoff_date','accrual_cutoff_date','prepaid_boundary_date','business_calendar','reversal_policy','prior_period_adjustment_policy','override_policy']) required_key(key) WHERE jsonb_typeof((child_row.snapshot#>'{settings}')->key)<>'string' OR btrim(child_row.snapshot#>>ARRAY['settings',key])='')
      WHEN 'tax' THEN EXISTS(SELECT 1 FROM unnest(ARRAY['jurisdiction','treatment','allocation_method','allocation_precision','residual_rule','expense_account_role','prepaid_account_role','accrual_account_role','coverage_start','coverage_end','effective_from']) required_key(key) WHERE jsonb_typeof((child_row.snapshot#>'{settings}')->key)<>'string' OR btrim(child_row.snapshot#>>ARRAY['settings',key])='') OR (child_row.snapshot#>'{settings,effective_to}' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(child_row.snapshot#>'{settings,effective_to}')<>'string' OR btrim(child_row.snapshot#>>'{settings,effective_to}')='')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,tax_codes}') t CROSS JOIN LATERAL unnest(ARRAY['code','rate','basis','recoverability','expense_treatment','effective_from']) required_key(key) WHERE jsonb_typeof(t->key)<>'string' OR btrim(t->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,tax_codes}') t WHERE t->'effective_to' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(t->'effective_to')<>'string' OR btrim(t->>'effective_to')=''))
      WHEN 'intercompany' THEN jsonb_typeof(child_row.snapshot#>'{settings,clearing_account_role}')<>'string' OR btrim(child_row.snapshot#>>'{settings,clearing_account_role}')='' OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,entities}') i CROSS JOIN LATERAL unnest(ARRAY['company_code','counterparty_entity_id','counterparty_approval_id','counterparty_approval_hash','currency','due_to_account_role','due_from_account_role','elimination_account_role','effective_from']) required_key(key) WHERE jsonb_typeof(i->key)<>'string' OR btrim(i->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,entities}') i WHERE i->'effective_to' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(i->'effective_to')<>'string' OR btrim(i->>'effective_to')=''))
      WHEN 'materiality' THEN EXISTS(SELECT 1 FROM unnest(ARRAY['currency','amount_drop_ratio','ap_aging_amount','budget_variance_amount','duplicate_amount','financial_statement_amount','loan_difference_amount','loan_excess_draw_amount','manual_je_amount','manual_round_amount','minimum_absolute_balance','minimum_open_amount','near_duplicate_amount','effective_from']) required_key(key) WHERE jsonb_typeof((child_row.snapshot#>'{settings}')->key)<>'string' OR btrim(child_row.snapshot#>>ARRAY['settings',key])='') OR (child_row.snapshot#>'{settings,effective_to}' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(child_row.snapshot#>'{settings,effective_to}')<>'string' OR btrim(child_row.snapshot#>>'{settings,effective_to}')=''))
      WHEN 'approval_thresholds' THEN EXISTS(SELECT 1 FROM unnest(ARRAY['currency','expense_amount_threshold','prepaid_amount_threshold','accrual_amount_threshold','cwip_amount_threshold']) required_key(key) WHERE jsonb_typeof((child_row.snapshot#>'{settings}')->key)<>'string' OR btrim(child_row.snapshot#>>ARRAY['settings',key])='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,approval_levels}') a CROSS JOIN LATERAL unnest(ARRAY['action','approver_role','confidence_band','effective_from','maximum_amount','minimum_amount','override_policy','poster_role','preparer_role','reviewer_role','risk_band','submit_permission','submitter_role','workflow']) required_key(key) WHERE jsonb_typeof(a->key)<>'string' OR btrim(a->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,approval_levels}') a WHERE a->'effective_to' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(a->'effective_to')<>'string' OR btrim(a->>'effective_to')='')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,classification_thresholds}') c CROSS JOIN LATERAL unnest(ARRAY['classification','confidence_band','effective_from','maximum_amount','minimum_amount','risk_band','workflow']) required_key(key) WHERE jsonb_typeof(c->key)<>'string' OR btrim(c->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,classification_thresholds}') c WHERE c->'effective_to' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(c->'effective_to')<>'string' OR btrim(c->>'effective_to')=''))
      WHEN 'loan_capitalization_policy' THEN EXISTS(SELECT 1 FROM unnest(ARRAY['currency','loan_purpose','capitalization_start_policy','suspension_policy','cessation_policy','eligible_interest_policy','eligible_fee_policy','expense_account_role','cwip_account_role','fixed_asset_account_role','materiality_amount','effective_from']) required_key(key) WHERE jsonb_typeof((child_row.snapshot#>'{settings}')->key)<>'string' OR btrim(child_row.snapshot#>>ARRAY['settings',key])='') OR (child_row.snapshot#>'{settings,effective_to}' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(child_row.snapshot#>'{settings,effective_to}')<>'string' OR btrim(child_row.snapshot#>>'{settings,effective_to}')='')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,qualifying_combinations}') q WHERE jsonb_typeof(q->'effective_from')<>'string' OR btrim(q->>'effective_from')='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,qualifying_combinations}') q CROSS JOIN LATERAL unnest(ARRAY['effective_to','asset_ref','project_ref','property_ref']) required_key(key) WHERE q->key IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(q->key)<>'string' OR btrim(q->>key)=''))
      WHEN 'report_mapping' THEN jsonb_typeof(child_row.snapshot#>'{settings,currency}')<>'string' OR btrim(child_row.snapshot#>>'{settings,currency}')='' OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m CROSS JOIN LATERAL unnest(ARRAY['account_code','account_role','cash_flow_class','effective_from','normal_balance','report_row_code','statement']) required_key(key) WHERE jsonb_typeof(m->key)<>'string' OR btrim(m->>key)='') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE m->'effective_to' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(m->'effective_to')<>'string' OR btrim(m->>'effective_to')=''))
      ELSE false END THEN RAISE EXCEPTION 'Approved AI settings contain an invalid required JSON string' USING ERRCODE='23514'; END IF;
    IF CASE child_key
      WHEN 'coa' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') a CROSS JOIN LATERAL jsonb_array_elements(a->'dimension_requirements') item WHERE jsonb_typeof(item)<>'string' OR btrim(item#>>'{}')='')
      WHEN 'vendor_treatment' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v CROSS JOIN LATERAL unnest(ARRAY['aliases','contract_keys','service_keys','source_requirements']) required_key(key) CROSS JOIN LATERAL jsonb_array_elements(v->key) item WHERE jsonb_typeof(item)<>'string' OR btrim(item#>>'{}')='')
      WHEN 'intercompany' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,entities}') i CROSS JOIN LATERAL jsonb_array_elements(i->'dimension_requirements') item WHERE jsonb_typeof(item)<>'string' OR btrim(item#>>'{}')='')
      WHEN 'tax' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,tax_codes}') t CROSS JOIN LATERAL jsonb_array_elements(t->'evidence_requirements') item WHERE jsonb_typeof(item)<>'string' OR btrim(item#>>'{}')='')
      WHEN 'loan_capitalization_policy' THEN EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,required_evidence}') item WHERE jsonb_typeof(item)<>'string' OR btrim(item#>>'{}')='')
      ELSE false END THEN RAISE EXCEPTION 'Approved AI settings contain an empty or non-string evidence key' USING ERRCODE='23514'; END IF;
    result:=result||jsonb_build_object(child_key,jsonb_build_object('tenant_id',p_tenant,'entity_id',p_entity,'period_id',p_period,'setting_snapshot_id',child_row.setting_snapshot_id,'version',child_row.version,'snapshot_hash',child_row.snapshot_hash,'schema_version',child_row.snapshot->>'schema_version','approval_status','APPROVED','approved_by',child_row.approved_by,'approved_at',child_row.approved_at,'settings',child_row.snapshot->'settings'));
  END LOOP;
  RETURN result||jsonb_build_object('can_create_draft',false,'can_review',false,'can_approve',false,'can_post',false);
END;
$$;

CREATE FUNCTION refs_accounting_settings_workflow_payload(p_tenant uuid,p_entity uuid,p_workflow uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE w accounting_settings_workflow;actor text:=refs_current_actor();hist jsonb;source_current boolean:=false;target_period_status period_status;forward_only_conflict boolean:=false;target_start date;
BEGIN
 SELECT * INTO w FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND accounting_settings_workflow_id=p_workflow;
 IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings workflow was not found' USING ERRCODE='P0002';END IF;
 SELECT status INTO target_period_status FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=w.period_id;
 target_start:=(w.canonical_parent_snapshot->>'period_start')::date;
 SELECT EXISTS(SELECT 1 FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED') AND (s.snapshot->>'period_end' IS NULL OR s.snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR s.snapshot->>'period_end'>=target_start::text))
  OR EXISTS(SELECT 1 FROM accounting_settings_workflow prior WHERE prior.tenant_id=p_tenant AND prior.entity_id=p_entity AND prior.accounting_settings_workflow_id<>p_workflow AND prior.status IN('ACTIVE','SUPERSEDED') AND (prior.canonical_parent_snapshot->>'period_end' IS NULL OR prior.canonical_parent_snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR prior.canonical_parent_snapshot->>'period_end'>=target_start::text)) INTO forward_only_conflict;
 BEGIN source_current:=refs_accounting_settings_parent_snapshot(p_tenant,p_entity,w.period_id,w.child_setting_snapshot_ids)=w.canonical_parent_snapshot;EXCEPTION WHEN others THEN source_current:=false;END;
 SELECT coalesce(jsonb_agg(jsonb_build_object('from_status',h.from_status,'to_status',h.to_status,'revision',h.revision::text,'actor_id',h.actor_id,'reason',h.reason,'previous_event_hash',h.previous_event_hash,'event_hash',h.event_hash,'created_at',h.created_at) ORDER BY h.revision),'[]'::jsonb) INTO hist FROM accounting_settings_workflow_history h WHERE h.tenant_id=p_tenant AND h.accounting_settings_workflow_id=p_workflow;
 RETURN jsonb_build_object('schema_version','ACCOUNTING_SETTINGS_WORKFLOW_V1','accounting_settings_workflow_id',w.accounting_settings_workflow_id,'tenant_id',w.tenant_id,'entity_id',w.entity_id,'period_id',w.period_id,'version',w.version::text,'status',w.status,'revision',w.revision::text,
  'child_setting_snapshot_ids',w.child_setting_snapshot_ids,'canonical_parent_snapshot',w.canonical_parent_snapshot,'canonical_parent_hash',w.canonical_parent_hash,'source_current',source_current,'target_period_status',target_period_status,'legacy_parent_setting_snapshot_id',w.legacy_parent_setting_snapshot_id,
  'created_by',w.created_by,'created_at',w.created_at,'submitted_by',w.submitted_by,'submitted_at',w.submitted_at,'reviewed_by',w.reviewed_by,'reviewed_at',w.reviewed_at,'approved_by',w.approved_by,'approved_at',w.approved_at,'activated_by',w.activated_by,'activated_at',w.activated_at,'superseded_by_workflow_id',w.superseded_by_workflow_id,'superseded_at',w.superseded_at,'history',hist,
  'action_flags',jsonb_build_object('can_submit',target_period_status='OPEN' AND NOT forward_only_conflict AND w.status='DRAFT' AND source_current AND actor IS DISTINCT FROM w.created_by AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW') AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.SUBMIT'),
   'can_review',target_period_status='OPEN' AND NOT forward_only_conflict AND w.status='SUBMITTED' AND source_current AND actor<>ALL(ARRAY[w.created_by,w.submitted_by]) AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW') AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.REVIEW'),
   'can_approve',target_period_status='OPEN' AND NOT forward_only_conflict AND w.status='REVIEWED' AND source_current AND actor<>ALL(ARRAY[w.created_by,w.submitted_by,w.reviewed_by]) AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW') AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.APPROVE'),
   'can_activate',target_period_status='OPEN' AND NOT forward_only_conflict AND w.status='APPROVED' AND source_current AND actor<>ALL(ARRAY[w.created_by,w.submitted_by,w.reviewed_by,w.approved_by]) AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW') AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.ACTIVATE')));
END;$$;

CREATE FUNCTION refs_read_accounting_settings_workflow(p_tenant uuid,p_entity uuid,p_workflow uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');RETURN refs_accounting_settings_workflow_payload(p_tenant,p_entity,p_workflow);END;$$;

CREATE FUNCTION refs_read_accounting_settings_workflow_evidence(p_tenant uuid,p_entity uuid,p_workflow uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE w accounting_settings_workflow;p accounting_period;selected jsonb;
BEGIN
 PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');
 SELECT * INTO w FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND accounting_settings_workflow_id=p_workflow;
 IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings workflow evidence was not found' USING ERRCODE='P0002';END IF;
 SELECT * INTO p FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=w.period_id;
 IF NOT FOUND OR refs_jsonb_hash(w.canonical_parent_snapshot)<>w.canonical_parent_hash OR w.canonical_parent_snapshot->>'period_id'<>w.period_id::text THEN RAISE EXCEPTION 'Accounting settings workflow parent evidence is invalid' USING ERRCODE='23514';END IF;
 selected:=refs_validate_accounting_settings_selected_bundle(p_tenant,p_entity,w.period_id,w.canonical_parent_snapshot,w.child_setting_snapshot_ids,true);
 RETURN jsonb_build_object('schema_version','ACCOUNTING_SETTINGS_WORKFLOW_EVIDENCE_V1','tenant_id',p_tenant,'entity_id',p_entity,'workflow_id',p_workflow,'period_id',w.period_id,'canonical_parent_hash',w.canonical_parent_hash,'canonical_parent_snapshot',w.canonical_parent_snapshot,'selected_child_snapshots',selected);
END;$$;
CREATE FUNCTION refs_read_accounting_settings_workflow_options(p_tenant uuid,p_entity uuid,p_period uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE p accounting_period;k text;fam text;rows jsonb:='[]'::jsonb;options jsonb;missing text[]:='{}';same_period boolean;forward_only_conflict boolean;forward_parent uuid;entity_active boolean:=false;actor text:=refs_current_actor();
 keys constant text[]:=ARRAY['coa','vendor_treatment','project_property_cost_code','period_close_policy','tax','intercompany','materiality','approval_thresholds','report_mapping','loan_capitalization_policy'];
 families constant text[]:=ARRAY['AI_ACCOUNTING_COA_V1','AI_ACCOUNTING_VENDOR_TREATMENT_V1','AI_ACCOUNTING_PROJECT_PROPERTY_COST_CODE_V1','AI_ACCOUNTING_PERIOD_CLOSE_POLICY_V1','AI_ACCOUNTING_TAX_V1','AI_ACCOUNTING_INTERCOMPANY_V1','AI_ACCOUNTING_MATERIALITY_V1','AI_ACCOUNTING_APPROVAL_THRESHOLDS_V1','AI_ACCOUNTING_REPORT_MAPPING_V1','AI_ACCOUNTING_LOAN_CAPITALIZATION_POLICY_V1'];
BEGIN
 PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');SELECT active INTO entity_active FROM entity WHERE tenant_id=p_tenant AND entity_id=p_entity;SELECT * INTO p FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period;
 IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings period was not found' USING ERRCODE='P0002';END IF;IF p.ledger_code<>'PRIMARY' THEN RAISE EXCEPTION 'Accounting settings require a PRIMARY ledger period' USING ERRCODE='23514';END IF;IF EXISTS(SELECT 1 FROM accounting_period other WHERE other.tenant_id=p_tenant AND other.entity_id=p_entity AND other.ledger_code='PRIMARY' AND other.period_id<>p.period_id AND daterange(other.starts_on,other.ends_on,'[]')&&daterange(p.starts_on,p.ends_on,'[]')) THEN RAISE EXCEPTION 'Accounting settings PRIMARY period range overlaps another period' USING ERRCODE='23514';END IF;
 FOR k,fam IN SELECT * FROM unnest(keys,families) LOOP
  SELECT coalesce(jsonb_agg(jsonb_build_object('setting_snapshot_id',s.setting_snapshot_id,'version',s.version::text,'snapshot_hash',s.snapshot_hash,'approved_by',s.approved_by,'approved_at',s.approved_at) ORDER BY s.version DESC,s.setting_snapshot_id DESC),'[]'::jsonb) INTO options
   FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family=fam AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status='APPROVED' AND s.snapshot_hash=refs_jsonb_hash(s.snapshot)
    AND s.effective_from<=p.starts_on::timestamptz AND(s.effective_to IS NULL OR s.effective_to>p.ends_on::timestamptz);
  IF jsonb_array_length(options)=0 THEN missing:=array_append(missing,fam);END IF;
  rows:=rows||jsonb_build_array(jsonb_build_object('key',k,'family',fam,'approved_options',options));
 END LOOP;
 SELECT EXISTS(SELECT 1 FROM accounting_settings_workflow w WHERE w.tenant_id=p_tenant AND w.entity_id=p_entity AND w.period_id=p_period AND w.status IN('ACTIVE','SUPERSEDED'))
  OR EXISTS(SELECT 1 FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED') AND s.effective_from>=p.starts_on::timestamptz AND s.effective_from<p.ends_on::timestamptz+interval '1 day') INTO same_period;
 SELECT EXISTS(SELECT 1 FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED') AND (s.snapshot->>'period_end' IS NULL OR s.snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR s.snapshot->>'period_end'>=p.starts_on::text))
  OR EXISTS(SELECT 1 FROM accounting_settings_workflow prior WHERE prior.tenant_id=p_tenant AND prior.entity_id=p_entity AND prior.status IN('ACTIVE','SUPERSEDED') AND (prior.canonical_parent_snapshot->>'period_end' IS NULL OR prior.canonical_parent_snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR prior.canonical_parent_snapshot->>'period_end'>=p.starts_on::text)) INTO forward_only_conflict;
 SELECT s.setting_snapshot_id INTO forward_parent FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status='APPROVED' AND s.effective_from<p.starts_on::timestamptz AND(s.effective_to IS NULL OR s.effective_to>p.starts_on::timestamptz) ORDER BY s.effective_from DESC,s.setting_snapshot_id DESC LIMIT 1;
 RETURN jsonb_build_object('schema_version','ACCOUNTING_SETTINGS_WORKFLOW_OPTIONS_V1','tenant_id',p_tenant,'entity_id',p_entity,'period_id',p_period,'prerequisites',rows,'blockers',jsonb_build_object('missing_approved_families',to_jsonb(missing),'same_period_activation_exists',same_period,'forward_only_conflict',forward_only_conflict,'forward_legacy_parent_setting_snapshot_id',forward_parent,'period_status',p.status,'replacement_policy','FORWARD_ONLY'),
  'action_flags',jsonb_build_object('can_create_draft',coalesce(entity_active,false) AND p.status='OPEN' AND cardinality(missing)=0 AND NOT same_period AND NOT forward_only_conflict AND actor IS NOT NULL AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW') AND refs_entity_has_permission(p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.CREATE')));
END;$$;

CREATE FUNCTION refs_create_accounting_settings_workflow(p_tenant uuid,p_entity uuid,p_period uuid,p_ids jsonb,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();idem idempotency_receipt;snapshot jsonb;wid uuid:=gen_random_uuid();v bigint;payload jsonb;result jsonb;p accounting_period;history_hash text;event_at timestamptz;
BEGIN
 IF NOT refs_accounting_settings_safe_text(actor,1,300) OR NOT refs_accounting_settings_safe_text(p_reason,8,2000) OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_accounting_settings_create_hash(p_tenant,p_entity,p_period,p_ids,p_reason) THEN RAISE EXCEPTION 'Invalid accounting settings create command' USING ERRCODE='22023';END IF;
 PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');
 PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.CREATE');
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'ACCOUNTING_SETTINGS_CREATE:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='ACCOUNTING_SETTINGS_CREATE:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Accounting settings create idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ACCOUNTING_SETTINGS:'||p_tenant::text||':'||p_entity::text,0));
 PERFORM 1 FROM entity WHERE tenant_id=p_tenant AND entity_id=p_entity AND active FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings entity was not found or active' USING ERRCODE='P0002';END IF;
 SELECT * INTO p FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings period was not found' USING ERRCODE='P0002';END IF;IF p.ledger_code<>'PRIMARY' THEN RAISE EXCEPTION 'Accounting settings require a PRIMARY ledger period' USING ERRCODE='23514';END IF;IF EXISTS(SELECT 1 FROM accounting_period other WHERE other.tenant_id=p_tenant AND other.entity_id=p_entity AND other.ledger_code='PRIMARY' AND other.period_id<>p.period_id AND daterange(other.starts_on,other.ends_on,'[]')&&daterange(p.starts_on,p.ends_on,'[]')) THEN RAISE EXCEPTION 'Accounting settings PRIMARY period range overlaps another period' USING ERRCODE='23514';END IF;IF p.status<>'OPEN' THEN RAISE EXCEPTION 'Accounting settings workflow requires an OPEN target period' USING ERRCODE='55000';END IF;
 LOCK TABLE setting_snapshot IN SHARE MODE;
 IF EXISTS(SELECT 1 FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND status IN('ACTIVE','SUPERSEDED'))
  OR EXISTS(SELECT 1 FROM setting_snapshot s JOIN accounting_period p ON p.tenant_id=p_tenant AND p.entity_id=p_entity AND p.period_id=p_period WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED') AND s.effective_from>=p.starts_on::timestamptz AND s.effective_from<p.ends_on::timestamptz+interval '1 day') THEN RAISE EXCEPTION 'Same-period accounting settings replacement is forbidden; choose a later target period' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED') AND (s.snapshot->>'period_end' IS NULL OR s.snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR s.snapshot->>'period_end'>=p.starts_on::text))
  OR EXISTS(SELECT 1 FROM accounting_settings_workflow prior WHERE prior.tenant_id=p_tenant AND prior.entity_id=p_entity AND prior.status IN('ACTIVE','SUPERSEDED') AND (prior.canonical_parent_snapshot->>'period_end' IS NULL OR prior.canonical_parent_snapshot->>'period_end'!~'^\d{4}-\d{2}-\d{2}$' OR prior.canonical_parent_snapshot->>'period_end'>=p.starts_on::text)) THEN RAISE EXCEPTION 'Accounting settings Draft must target a period strictly later than retained parent history' USING ERRCODE='55000';END IF;
 snapshot:=refs_accounting_settings_parent_snapshot(p_tenant,p_entity,p_period,p_ids);
 SELECT coalesce(max(version),0)+1 INTO v FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity;
 event_at:=clock_timestamp();
 INSERT INTO accounting_settings_workflow(accounting_settings_workflow_id,tenant_id,entity_id,period_id,version,child_setting_snapshot_ids,canonical_parent_snapshot,canonical_parent_hash,created_by,created_at) VALUES(wid,p_tenant,p_entity,p_period,v,p_ids,snapshot,refs_jsonb_hash(snapshot),actor,event_at);
 history_hash:=refs_accounting_settings_history_hash(p_tenant,wid,NULL,'DRAFT',0,actor,p_reason,NULL,event_at);
 payload:=jsonb_build_object('workflow_id',wid,'status','DRAFT','revision','0','version',v::text,'period_id',p_period,'canonical_parent_hash',refs_jsonb_hash(snapshot),'actor_id',actor,'reason',btrim(p_reason),'previous_event_hash',NULL,'history_event_hash',history_hash,'created_at',event_at);
 INSERT INTO accounting_settings_workflow_history(accounting_settings_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,previous_event_hash,event_hash,created_at) VALUES(wid,p_tenant,NULL,'DRAFT',0,actor,btrim(p_reason),NULL,history_hash,event_at);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_DRAFT_CREATED','ACCOUNTING_SETTINGS_WORKFLOW',wid,'CREATE',actor,'USER','ACCOUNTING.SETTINGS.WORKFLOW.CREATE',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_WORKFLOW',wid,'ACCOUNTING_SETTINGS_DRAFT_CREATED',payload,refs_jsonb_hash(payload));
 result:=refs_accounting_settings_workflow_payload(p_tenant,p_entity,wid)||jsonb_build_object('idempotent',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=result,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN result;
END;$$;

CREATE FUNCTION refs_transition_accounting_settings_workflow(p_tenant uuid,p_entity uuid,p_workflow uuid,p_action text,p_expected_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor text:=refs_current_actor();action text:=upper(p_action);permission text;next_status text;idem idempotency_receipt;w accounting_settings_workflow;initial accounting_settings_workflow;p accounting_period;snapshot jsonb;payload jsonb;result jsonb;oldw accounting_settings_workflow;oldparent setting_snapshot;parent_id uuid:=gen_random_uuid();parent_version bigint;readback jsonb;target_start date;latest_parent_period_end date;latest_workflow_period_end date;previous_hash text;history_hash text;old_previous_hash text;old_history_hash text;event_at timestamptz;old_event_at timestamptz;
BEGIN
 IF action IS NULL OR action NOT IN('SUBMIT','REVIEW','APPROVE','ACTIVATE') OR NOT refs_accounting_settings_safe_text(actor,1,300) OR p_expected_revision IS NULL OR p_expected_revision<0 OR NOT refs_accounting_settings_safe_text(p_reason,8,2000) OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_accounting_settings_transition_hash(p_tenant,p_entity,p_workflow,action,p_expected_revision,p_reason) THEN RAISE EXCEPTION 'Invalid accounting settings transition command' USING ERRCODE='22023';END IF;
 permission:='ACCOUNTING.SETTINGS.WORKFLOW.'||action;PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');PERFORM refs_assert_scope(p_tenant,p_entity,permission);
 INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'ACCOUNTING_SETTINGS_'||action||':'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;
 SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='ACCOUNTING_SETTINGS_'||action||':'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;
 IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Accounting settings transition idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('ACCOUNTING_SETTINGS:'||p_tenant::text||':'||p_entity::text,0));
 PERFORM 1 FROM entity WHERE tenant_id=p_tenant AND entity_id=p_entity AND active FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings entity was not found or active' USING ERRCODE='P0002';END IF;
 SELECT * INTO initial FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND accounting_settings_workflow_id=p_workflow;
 IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings workflow was not found' USING ERRCODE='P0002';END IF;
 SELECT * INTO p FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=initial.period_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Accounting settings period was not found' USING ERRCODE='P0002';END IF;IF p.ledger_code<>'PRIMARY' THEN RAISE EXCEPTION 'Accounting settings require a PRIMARY ledger period' USING ERRCODE='23514';END IF;IF EXISTS(SELECT 1 FROM accounting_period other WHERE other.tenant_id=p_tenant AND other.entity_id=p_entity AND other.ledger_code='PRIMARY' AND other.period_id<>p.period_id AND daterange(other.starts_on,other.ends_on,'[]')&&daterange(p.starts_on,p.ends_on,'[]')) THEN RAISE EXCEPTION 'Accounting settings PRIMARY period range overlaps another period' USING ERRCODE='23514';END IF;IF p.status<>'OPEN' THEN RAISE EXCEPTION 'Accounting settings transition requires the target period to remain OPEN' USING ERRCODE='55000';END IF;
 SELECT * INTO w FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND accounting_settings_workflow_id=p_workflow FOR UPDATE;
 SELECT event_hash INTO previous_hash FROM accounting_settings_workflow_history WHERE tenant_id=p_tenant AND accounting_settings_workflow_id=p_workflow AND revision=w.revision;
 IF previous_hash IS NULL THEN RAISE EXCEPTION 'Accounting settings history chain is incomplete' USING ERRCODE='23514';END IF;
 LOCK TABLE setting_snapshot IN SHARE ROW EXCLUSIVE MODE;snapshot:=refs_accounting_settings_parent_snapshot(p_tenant,p_entity,w.period_id,w.child_setting_snapshot_ids);
 IF snapshot IS DISTINCT FROM w.canonical_parent_snapshot OR refs_jsonb_hash(snapshot)<>w.canonical_parent_hash THEN RAISE EXCEPTION 'Accounting settings source evidence changed' USING ERRCODE='40001';END IF;
 target_start:=(snapshot->>'period_start')::date;
 SELECT max(CASE WHEN s.snapshot->>'period_end'~'^\d{4}-\d{2}-\d{2}$' THEN (s.snapshot->>'period_end')::date ELSE 'infinity'::date END) INTO latest_parent_period_end FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status IN('APPROVED','RETIRED');
 SELECT max(CASE WHEN prior.canonical_parent_snapshot->>'period_end'~'^\d{4}-\d{2}-\d{2}$' THEN (prior.canonical_parent_snapshot->>'period_end')::date ELSE 'infinity'::date END) INTO latest_workflow_period_end FROM accounting_settings_workflow prior WHERE prior.tenant_id=p_tenant AND prior.entity_id=p_entity AND prior.accounting_settings_workflow_id<>p_workflow AND prior.status IN('ACTIVE','SUPERSEDED');
 IF (latest_parent_period_end IS NOT NULL AND latest_parent_period_end>=target_start) OR (latest_workflow_period_end IS NOT NULL AND latest_workflow_period_end>=target_start) THEN RAISE EXCEPTION 'Accounting settings transition must remain strictly later than all retained parent history' USING ERRCODE='55000';END IF;
 next_status:=CASE action WHEN 'SUBMIT' THEN 'SUBMITTED' WHEN 'REVIEW' THEN 'REVIEWED' WHEN 'APPROVE' THEN 'APPROVED' ELSE 'ACTIVE' END;
 IF w.revision<>p_expected_revision THEN RAISE EXCEPTION 'Accounting settings revision conflict' USING ERRCODE='40001';END IF;
 IF (action='SUBMIT' AND w.status<>'DRAFT') OR(action='REVIEW' AND w.status<>'SUBMITTED') OR(action='APPROVE' AND w.status<>'REVIEWED') OR(action='ACTIVATE' AND w.status<>'APPROVED') THEN RAISE EXCEPTION 'Accounting settings status conflict' USING ERRCODE='40001';END IF;
 IF (action='SUBMIT' AND actor=w.created_by) OR(action='REVIEW' AND actor=ANY(ARRAY[w.created_by,w.submitted_by])) OR(action='APPROVE' AND actor=ANY(ARRAY[w.created_by,w.submitted_by,w.reviewed_by])) OR(action='ACTIVATE' AND actor=ANY(ARRAY[w.created_by,w.submitted_by,w.reviewed_by,w.approved_by])) THEN RAISE EXCEPTION 'Accounting settings separation of duties violation' USING ERRCODE='42501';END IF;
 IF action='ACTIVATE' THEN
  SELECT * INTO oldw FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='ACTIVE' FOR UPDATE;
  IF oldw.accounting_settings_workflow_id IS NOT NULL THEN
   IF (snapshot->>'period_start')::date<=(oldw.canonical_parent_snapshot->>'period_start')::date THEN RAISE EXCEPTION 'Accounting settings replacement must target a strictly later period' USING ERRCODE='55000';END IF;
   SELECT * INTO oldparent FROM setting_snapshot WHERE tenant_id=p_tenant AND entity_id=p_entity AND setting_snapshot_id=oldw.legacy_parent_setting_snapshot_id FOR UPDATE;
   IF oldparent.status<>'APPROVED' OR oldparent.effective_from>=(snapshot->>'period_start')::date::timestamptz OR(oldparent.effective_to IS NOT NULL AND oldparent.effective_to<(snapshot->>'period_start')::date::timestamptz) THEN RAISE EXCEPTION 'Prior active parent cannot be retired safely' USING ERRCODE='55000';END IF;
   IF actor=ANY(ARRAY[oldparent.created_by,oldparent.approved_by]) THEN RAISE EXCEPTION 'Activator cannot retire a parent they created or approved' USING ERRCODE='42501';END IF;
   IF oldparent.snapshot_hash<>refs_jsonb_hash(oldparent.snapshot) OR oldparent.snapshot->>'period_end' !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Prior active parent period evidence is invalid' USING ERRCODE='23514';END IF;
   IF target_start<=(oldparent.snapshot->>'period_end')::date THEN RAISE EXCEPTION 'Accounting settings replacement cannot truncate a prior period' USING ERRCODE='55000';END IF;
   INSERT INTO accounting_settings_workflow_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,oldw.accounting_settings_workflow_id,'PARENT_RETIRE');
   PERFORM set_config('refs.config_retire','authorized',true);
   UPDATE setting_snapshot SET status='RETIRED',effective_to=(snapshot->>'period_start')::date::timestamptz,retired_by=actor,retired_at=clock_timestamp(),retire_reason='Superseded by forward accounting settings activation',lifecycle_revision=lifecycle_revision+1 WHERE setting_snapshot_id=oldparent.setting_snapshot_id;
   PERFORM set_config('refs.config_retire','',true);
   DELETE FROM accounting_settings_workflow_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND accounting_settings_workflow_id=oldw.accounting_settings_workflow_id AND operation='PARENT_RETIRE';
   payload:=jsonb_build_object('snapshot_id',oldparent.setting_snapshot_id,'status','RETIRED','effective_to',snapshot->>'period_start','workflow_id',p_workflow);
   INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONFIG_SNAPSHOT_RETIRED','SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'RETIRE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
   INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'CONFIG_SNAPSHOT_RETIRED',payload,refs_jsonb_hash(payload));
   INSERT INTO accounting_settings_workflow_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,oldw.accounting_settings_workflow_id,'SUPERSEDED');
   old_event_at:=clock_timestamp();
   UPDATE accounting_settings_workflow SET status='SUPERSEDED',revision=revision+1,superseded_by_workflow_id=p_workflow,superseded_at=old_event_at WHERE accounting_settings_workflow_id=oldw.accounting_settings_workflow_id;
   DELETE FROM accounting_settings_workflow_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND accounting_settings_workflow_id=oldw.accounting_settings_workflow_id AND operation='SUPERSEDED';
   SELECT event_hash INTO old_previous_hash FROM accounting_settings_workflow_history WHERE tenant_id=p_tenant AND accounting_settings_workflow_id=oldw.accounting_settings_workflow_id AND revision=oldw.revision;
   IF old_previous_hash IS NULL THEN RAISE EXCEPTION 'Prior accounting settings history chain is incomplete' USING ERRCODE='23514';END IF;
   old_history_hash:=refs_accounting_settings_history_hash(p_tenant,oldw.accounting_settings_workflow_id,'ACTIVE','SUPERSEDED',oldw.revision+1,actor,p_reason,old_previous_hash,old_event_at);
   payload:=jsonb_build_object('workflow_id',oldw.accounting_settings_workflow_id,'from_status','ACTIVE','status','SUPERSEDED','revision',(oldw.revision+1)::text,'actor_id',actor,'reason',btrim(p_reason),'previous_event_hash',old_previous_hash,'history_event_hash',old_history_hash,'superseded_by_workflow_id',p_workflow,'retired_parent_setting_snapshot_id',oldparent.setting_snapshot_id,'created_at',old_event_at);
   INSERT INTO accounting_settings_workflow_history(accounting_settings_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,previous_event_hash,event_hash,created_at) VALUES(oldw.accounting_settings_workflow_id,p_tenant,'ACTIVE','SUPERSEDED',oldw.revision+1,actor,btrim(p_reason),old_previous_hash,old_history_hash,old_event_at);
   INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_SUPERSEDED','ACCOUNTING_SETTINGS_WORKFLOW',oldw.accounting_settings_workflow_id,'SUPERSEDE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
   INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_WORKFLOW',oldw.accounting_settings_workflow_id,'ACCOUNTING_SETTINGS_SUPERSEDED',payload,refs_jsonb_hash(payload));
  ELSE
   SELECT * INTO oldparent FROM setting_snapshot s WHERE s.tenant_id=p_tenant AND s.entity_id=p_entity AND s.family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND s.scope_type='ENTITY' AND s.scope_key=p_entity::text AND s.status='APPROVED' AND s.effective_from<=(snapshot->>'period_start')::date::timestamptz AND(s.effective_to IS NULL OR s.effective_to>(snapshot->>'period_start')::date::timestamptz) FOR UPDATE;
   IF oldparent.setting_snapshot_id IS NOT NULL THEN
    IF oldparent.effective_from>=(snapshot->>'period_start')::date::timestamptz THEN RAISE EXCEPTION 'Same-period legacy settings replacement is forbidden' USING ERRCODE='55000';END IF;
    IF actor=ANY(ARRAY[oldparent.created_by,oldparent.approved_by]) THEN RAISE EXCEPTION 'Activator cannot retire a parent they created or approved' USING ERRCODE='42501';END IF;
    IF oldparent.snapshot_hash<>refs_jsonb_hash(oldparent.snapshot) OR oldparent.snapshot->>'period_end' !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Legacy parent period evidence is invalid' USING ERRCODE='23514';END IF;
    IF target_start<=(oldparent.snapshot->>'period_end')::date THEN RAISE EXCEPTION 'Accounting settings replacement cannot truncate a prior period' USING ERRCODE='55000';END IF;
    PERFORM set_config('refs.config_retire','authorized',true);
    UPDATE setting_snapshot SET status='RETIRED',effective_to=(snapshot->>'period_start')::date::timestamptz,retired_by=actor,retired_at=clock_timestamp(),retire_reason='Adopted by forward accounting settings workflow activation',lifecycle_revision=lifecycle_revision+1 WHERE setting_snapshot_id=oldparent.setting_snapshot_id;
    PERFORM set_config('refs.config_retire','',true);
    payload:=jsonb_build_object('snapshot_id',oldparent.setting_snapshot_id,'status','RETIRED','effective_to',snapshot->>'period_start','workflow_id',p_workflow);
    INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONFIG_SNAPSHOT_RETIRED','SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'RETIRE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
    INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'SETTING_SNAPSHOT',oldparent.setting_snapshot_id,'CONFIG_SNAPSHOT_RETIRED',payload,refs_jsonb_hash(payload));
   END IF;
  END IF;
  SELECT coalesce(max(version),0)+1 INTO parent_version FROM setting_snapshot WHERE tenant_id=p_tenant AND family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1' AND scope_type='ENTITY' AND scope_key=p_entity::text;
  INSERT INTO setting_snapshot(setting_snapshot_id,tenant_id,entity_id,family,scope_type,scope_key,version,effective_from,effective_to,status,snapshot,snapshot_hash,created_by,approved_by,approved_at)
   VALUES(parent_id,p_tenant,p_entity,'AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1','ENTITY',p_entity::text,parent_version,(snapshot->>'period_start')::date::timestamptz,NULL,'APPROVED',snapshot,refs_jsonb_hash(snapshot),w.created_by,w.approved_by,w.approved_at);
  readback:=refs_validate_accounting_settings_activation_snapshot(p_tenant,p_entity,w.period_id);
  IF readback->>'settings_snapshot_id'<>parent_id::text OR readback->>'settings_hash'<>refs_jsonb_hash(snapshot) THEN RAISE EXCEPTION 'Activated settings failed authoritative readback' USING ERRCODE='23514';END IF;
  payload:=jsonb_build_object('setting_snapshot_id',parent_id,'tenant_id',p_tenant,'entity_id',p_entity,'family','AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1','version',parent_version::text,'effective_from',target_start::text,'snapshot_hash',refs_jsonb_hash(snapshot),'workflow_id',p_workflow,'approved_by',w.approved_by,'activated_by',actor);
  INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'CONFIG_SNAPSHOT_APPROVED','SETTING_SNAPSHOT',parent_id,'APPROVE',actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
  INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'SETTING_SNAPSHOT',parent_id,'CONFIG_SNAPSHOT_APPROVED',payload,refs_jsonb_hash(payload));
 END IF;
 event_at:=clock_timestamp();
 INSERT INTO accounting_settings_workflow_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_workflow,next_status);
 UPDATE accounting_settings_workflow SET status=next_status,revision=revision+1,
  submitted_by=CASE WHEN action='SUBMIT' THEN actor ELSE submitted_by END,submitted_at=CASE WHEN action='SUBMIT' THEN event_at ELSE submitted_at END,
  reviewed_by=CASE WHEN action='REVIEW' THEN actor ELSE reviewed_by END,reviewed_at=CASE WHEN action='REVIEW' THEN event_at ELSE reviewed_at END,
  approved_by=CASE WHEN action='APPROVE' THEN actor ELSE approved_by END,approved_at=CASE WHEN action='APPROVE' THEN event_at ELSE approved_at END,
  activated_by=CASE WHEN action='ACTIVATE' THEN actor ELSE activated_by END,activated_at=CASE WHEN action='ACTIVATE' THEN event_at ELSE activated_at END,
  legacy_parent_setting_snapshot_id=CASE WHEN action='ACTIVATE' THEN parent_id ELSE legacy_parent_setting_snapshot_id END WHERE accounting_settings_workflow_id=p_workflow;
 DELETE FROM accounting_settings_workflow_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND accounting_settings_workflow_id=p_workflow AND operation=next_status;
 history_hash:=refs_accounting_settings_history_hash(p_tenant,p_workflow,w.status,next_status,w.revision+1,actor,p_reason,previous_hash,event_at);
 payload:=jsonb_build_object('workflow_id',p_workflow,'from_status',w.status,'status',next_status,'revision',(w.revision+1)::text,'actor_id',actor,'reason',btrim(p_reason),'previous_event_hash',previous_hash,'history_event_hash',history_hash,'legacy_parent_setting_snapshot_id',CASE WHEN action='ACTIVATE' THEN parent_id ELSE NULL END,'canonical_parent_hash',w.canonical_parent_hash,'created_at',event_at);
 INSERT INTO accounting_settings_workflow_history(accounting_settings_workflow_id,tenant_id,from_status,to_status,revision,actor_id,reason,previous_event_hash,event_hash,created_at) VALUES(p_workflow,p_tenant,w.status,next_status,w.revision+1,actor,btrim(p_reason),previous_hash,history_hash,event_at);
 INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_'||action,'ACCOUNTING_SETTINGS_WORKFLOW',p_workflow,action,actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);
 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'ACCOUNTING_SETTINGS_WORKFLOW',p_workflow,'ACCOUNTING_SETTINGS_'||action,payload,refs_jsonb_hash(payload));
 result:=refs_accounting_settings_workflow_payload(p_tenant,p_entity,p_workflow)||jsonb_build_object('idempotent',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=result,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN result;
END;$$;

CREATE FUNCTION refs_read_accounting_settings_workflow_register(p_tenant uuid,p_entity uuid,p_limit integer DEFAULT 50) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE rows jsonb;BEGIN PERFORM refs_assert_scope(p_tenant,p_entity,'ACCOUNTING.SETTINGS.WORKFLOW.VIEW');IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid accounting settings workflow limit' USING ERRCODE='22023';END IF;
 SELECT coalesce(jsonb_agg(refs_accounting_settings_workflow_payload(p_tenant,p_entity,w.accounting_settings_workflow_id) ORDER BY w.created_at DESC,w.accounting_settings_workflow_id DESC),'[]'::jsonb) INTO rows FROM(SELECT * FROM accounting_settings_workflow WHERE tenant_id=p_tenant AND entity_id=p_entity ORDER BY created_at DESC,accounting_settings_workflow_id DESC LIMIT p_limit)w;
 RETURN jsonb_build_object('schema_version','ACCOUNTING_SETTINGS_WORKFLOW_REGISTER_V1','tenant_id',p_tenant,'entity_id',p_entity,'rows',rows,'limit',p_limit,'boundary','PARENT_SNAPSHOT_ACTIVATION_ONLY');END;$$;

REVOKE ALL ON FUNCTION refs_validate_accounting_settings_selected_bundle(uuid,uuid,uuid,jsonb,jsonb,boolean),refs_validate_accounting_settings_activation_snapshot(uuid,uuid,uuid),refs_accounting_settings_parent_snapshot(uuid,uuid,uuid,jsonb),refs_accounting_settings_create_hash(uuid,uuid,uuid,jsonb,text),refs_accounting_settings_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_accounting_settings_safe_text(text,integer,integer),refs_accounting_settings_history_hash(uuid,uuid,text,text,bigint,text,text,text,timestamptz),refs_accounting_settings_workflow_payload(uuid,uuid,uuid),refs_read_accounting_settings_workflow(uuid,uuid,uuid),refs_read_accounting_settings_workflow_evidence(uuid,uuid,uuid),refs_read_accounting_settings_workflow_options(uuid,uuid,uuid),refs_create_accounting_settings_workflow(uuid,uuid,uuid,jsonb,text,text,text),refs_transition_accounting_settings_workflow(uuid,uuid,uuid,text,bigint,text,text,text),refs_read_accounting_settings_workflow_register(uuid,uuid,integer) FROM PUBLIC,refs_app;
GRANT EXECUTE ON FUNCTION refs_accounting_settings_create_hash(uuid,uuid,uuid,jsonb,text),refs_accounting_settings_transition_hash(uuid,uuid,uuid,text,bigint,text),refs_read_accounting_settings_workflow(uuid,uuid,uuid),refs_read_accounting_settings_workflow_evidence(uuid,uuid,uuid),refs_read_accounting_settings_workflow_options(uuid,uuid,uuid),refs_create_accounting_settings_workflow(uuid,uuid,uuid,jsonb,text,text,text),refs_transition_accounting_settings_workflow(uuid,uuid,uuid,text,bigint,text,text,text),refs_read_accounting_settings_workflow_register(uuid,uuid,integer) TO refs_app;

COMMIT;
